def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)
import json
_FIELDS = ("payload", "done", "token", "until", "attempts", "dead")
class Queue:
    def __init__(self, max_attempts=3):
        if not _is_int(max_attempts) or max_attempts <= 0: raise ValueError("max_attempts must be a positive integer")
        self.items = {}; self.serial = 0; self.max_attempts = max_attempts; self.seen = {}
    def enqueue(self, key, payload):
        if key not in self.items:
            self.items[key] = {"payload": payload, "done": False, "token": None, "until": None, "attempts": 0, "dead": False}
    def claim(self, key, now=0, ttl=10):
        if not _is_int(now) or now < 0: raise ValueError("now must be an integer >= 0")
        if not _is_int(ttl) or ttl <= 0: raise ValueError("ttl must be an integer > 0")
        row = self.items.get(key)
        if row is None or row["done"] or row["dead"]: return None
        if row["token"] is not None:
            if now < row["until"]: return None
            row["token"] = None; row["until"] = None
        if row["attempts"] >= self.max_attempts:
            row["dead"] = True; return None
        self.serial += 1; row["token"] = self.serial; row["until"] = now + ttl; row["attempts"] += 1
        return row["payload"], self.serial
    def ack(self, key, token):
        row = self.items.get(key)
        if not row or row["done"] or row["dead"] or row["token"] is None or row["token"] != token: return False
        row["done"] = True; return True
    def retry(self, key, token):
        row = self.items.get(key)
        if not row or row["done"] or row["dead"] or row["token"] is None or row["token"] != token: return False
        row["token"] = None; row["until"] = None
        if row["attempts"] >= self.max_attempts: row["dead"] = True
        return True
    def dumps(self):
        return json.dumps({"version": 2, "serial": self.serial, "max_attempts": self.max_attempts,
                           "items": {k: {f: r[f] for f in _FIELDS} for k, r in self.items.items()}, "seen": self.seen})
    @classmethod
    def loads(cls, text):
        try: data = json.loads(text)
        except (TypeError, ValueError) as e: raise ValueError("malformed snapshot: %s" % e)
        if not isinstance(data, dict): raise ValueError("snapshot must be an object")
        if not _is_int(data.get("version")) or data["version"] != 2: raise ValueError("unsupported snapshot version")
        for f in ("serial", "max_attempts", "items", "seen"):
            if f not in data: raise ValueError("missing snapshot field: " + f)
        if not _is_int(data["serial"]) or data["serial"] < 0: raise ValueError("invalid serial")
        if not isinstance(data["items"], dict) or not isinstance(data["seen"], dict): raise ValueError("invalid items or seen")
        q = cls(data["max_attempts"]); q.serial = data["serial"]; q.seen = data["seen"]
        for key, r in data["items"].items():
            if not isinstance(r, dict): raise ValueError("invalid item: " + key)
            for f in _FIELDS:
                if f not in r: raise ValueError("missing item field: " + f)
            for f in ("done", "dead"):
                if not isinstance(r[f], bool): raise ValueError("invalid item field: " + f)
            for f in ("token", "until"):
                if r[f] is not None and (not _is_int(r[f]) or r[f] < 0): raise ValueError("invalid item field: " + f)
            if not _is_int(r["attempts"]) or r["attempts"] < 0: raise ValueError("invalid item field: attempts")
            if (r["token"] is None) != (r["until"] is None): raise ValueError("token and until must be set together")
            q.items[key] = {f: r[f] for f in _FIELDS}
            if r["token"] is not None: q.serial = max(q.serial, r["token"])
        return q
